"""
Scoring script: read inference JSONL, extract answers, compute exact-match scores.

Input:  JSONL from run_inference.py
Output: JSONL with added 'score' and 'extracted_answer' fields.
Deps:   (stdlib only)
"""

import argparse
import json
import re
from pathlib import Path


def extract_gsm8k_answer(text: str) -> str | None:
    """Extract numeric answer from GSM8K-style output.

    Looks for '#### <number>' first, then falls back to the last standalone number.
    """
    m = re.search(r"####\s*([+-]?[\d,]+\.?\d*)", text)
    if m:
        return m.group(1).replace(",", "")
    numbers = re.findall(r"(?<![.\w])[+-]?[\d,]+\.?\d*(?![.\w])", text)
    if numbers:
        return numbers[-1].replace(",", "")
    return None


def normalize_number(s: str | None) -> float | None:
    if s is None:
        return None
    s = s.replace(",", "").strip()
    try:
        return float(s)
    except ValueError:
        return None


def extract_gsm8k_reference(ref: str) -> str:
    """Extract the numeric answer from GSM8K reference (after ####)."""
    m = re.search(r"####\s*([+-]?[\d,]+\.?\d*)", ref)
    if m:
        return m.group(1).replace(",", "")
    return ref.strip()


def score_gsm8k(generated: str, reference: str) -> tuple[int, str | None]:
    extracted = extract_gsm8k_answer(generated)
    ref_num = normalize_number(extract_gsm8k_reference(reference))
    pred_num = normalize_number(extracted)
    if ref_num is not None and pred_num is not None and ref_num == pred_num:
        return 1, extracted
    return 0, extracted


def extract_letter(text: str) -> str | None:
    """Extract a single option letter (A/B/C/D) from text."""
    m = re.search(r"\b([A-D])\b", text.strip().upper())
    return m.group(1) if m else None


def score_mmlu(generated: str, reference: str) -> tuple[int, str | None]:
    extracted = extract_letter(generated)
    ref_letter = extract_letter(reference)
    if extracted and ref_letter and extracted == ref_letter:
        return 1, extracted
    return 0, extracted


def extract_option_number(text: str) -> str | None:
    numbers = re.findall(r"\b([0-3])\b", text.strip())
    return numbers[-1] if numbers else None


def score_hellaswag(generated: str, reference: str) -> tuple[int, str | None]:
    extracted = extract_option_number(generated)
    ref_num = reference.strip()
    if extracted and extracted == ref_num:
        return 1, extracted
    return 0, extracted


SCORERS: dict[str, callable] = {
    "gsm8k": score_gsm8k,
    "mmlu": score_mmlu,
    "hellaswag": score_hellaswag,
}


def score_file(input_path: str, output_path: str, benchmark: str) -> None:
    if benchmark == "humaneval":
        raise NotImplementedError("HumanEval scoring requires code execution sandbox (TODO)")

    scorer = SCORERS.get(benchmark)
    if scorer is None:
        raise ValueError(f"Unsupported benchmark: {benchmark}")

    records: list[dict] = []
    with open(input_path) as f:
        for line in f:
            records.append(json.loads(line))

    total, correct = 0, 0
    scored: list[dict] = []
    for rec in records:
        s, extracted = scorer(rec["generated_text"], rec["reference_answer"])
        rec["score"] = s
        rec["extracted_answer"] = extracted
        scored.append(rec)
        total += 1
        correct += s

    out = Path(output_path)
    out.parent.mkdir(parents=True, exist_ok=True)
    with open(out, "w") as f:
        for rec in scored:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")

    acc = correct / total if total else 0
    print(f"Scored {total} items: {correct}/{total} = {acc:.4f}")


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Score inference outputs by benchmark")
    parser.add_argument("--input_path", type=str, required=True, help="Input JSONL from run_inference.py")
    parser.add_argument("--output_path", type=str, required=True, help="Output JSONL with scores")
    parser.add_argument("--benchmark", type=str, default="gsm8k", help="Benchmark name")
    return parser.parse_args()


if __name__ == "__main__":
    a = parse_args()
    score_file(a.input_path, a.output_path, a.benchmark)

#!/usr/bin/env Rscript
# G-Theory variance component estimation via crossed random-effects models.
# Supports condition-level (lmer) and item-level (glmer) fitting modes.
# Outputs variance component table as CSV and JSON.

suppressPackageStartupMessages({
  library(lme4)
  library(boot)
  library(readr)
  library(dplyr)
  library(jsonlite)
})

# ── CLI argument parsing ─────────────────────────────────────────────────────

parse_args <- function() {
  args <- commandArgs(trailingOnly = TRUE)
  opts <- list(
    input      = NULL,
    output_dir = ".",
    mode       = "condition",
    n_boot     = 1000L
  )

  i <- 1L
  while (i <= length(args)) {
    key <- args[i]
    if (key %in% c("--input", "--output_dir", "--mode", "--n_boot")) {
      i <- i + 1L
      val <- args[i]
      name <- sub("^--", "", key)
      if (name == "n_boot") val <- as.integer(val)
      opts[[name]] <- val
    } else if (key %in% c("-h", "--help")) {
      cat("Usage: Rscript fit_gtheory.R --input <csv> [--output_dir <dir>] [--mode condition|item] [--n_boot 1000]\n")
      cat("\nOptions:\n")
      cat("  --input       Input CSV path (required)\n")
      cat("  --output_dir  Output directory (default: .)\n")
      cat("  --mode        'condition' (lmer on accuracy) or 'item' (glmer on binary score) [default: condition]\n")
      cat("  --n_boot      Bootstrap iterations for CIs [default: 1000]\n")
      quit(status = 0)
    } else {
      stop(sprintf("Unknown argument: %s", key))
    }
    i <- i + 1L
  }

  if (is.null(opts$input)) stop("--input is required")
  if (!opts$mode %in% c("condition", "item")) stop("--mode must be 'condition' or 'item'")
  opts
}

# ── Facet helpers ────────────────────────────────────────────────────────────

MAIN_FACETS <- c("model", "precision", "temperature", "seed", "prompt_template_id")

INTERACTION_TERMS <- c(
  "model:precision",
  "model:temperature",
  "precision:temperature",
  "model:prompt_template_id",
  "seed:prompt_template_id"
)

ensure_factors <- function(df, facets) {
  for (f in facets) {
    if (f %in% names(df)) {
      df[[f]] <- as.factor(df[[f]])
    }
  }
  df
}

detect_available_facets <- function(df, candidates) {
  present <- candidates[candidates %in% names(df)]
  # drop facets with < 2 levels (no variance to estimate)
  keep <- vapply(present, function(f) length(unique(df[[f]])) >= 2L, logical(1))
  present[keep]
}

# ── Model fitting ────────────────────────────────────────────────────────────

build_formula <- function(facets, interactions, response, family = "gaussian") {
  re_terms <- paste0("(1|", facets, ")")
  valid_ixn <- Filter(function(ix) {
    parts <- strsplit(ix, ":")[[1]]
    all(parts %in% facets)
  }, interactions)
  if (length(valid_ixn) > 0) {
    re_terms <- c(re_terms, paste0("(1|", valid_ixn, ")"))
  }
  as.formula(paste(response, "~ 1 +", paste(re_terms, collapse = " + ")))
}

fit_condition_mode <- function(df, facets) {
  # Expects columns: facets + accuracy
  required <- c(facets, "accuracy")
  missing <- setdiff(required, names(df))
  if (length(missing) > 0) stop(paste("Missing columns:", paste(missing, collapse = ", ")))

  # Aggregate to condition level if not already
  df_agg <- df %>%
    group_by(across(all_of(facets))) %>%
    summarise(accuracy = mean(accuracy, na.rm = TRUE), .groups = "drop")

  frm <- build_formula(facets, INTERACTION_TERMS, "accuracy")
  cat("Fitting lmer:", deparse(frm), "\n")
  lmer(frm, data = df_agg, REML = TRUE,
       control = lmerControl(optimizer = "bobyqa", optCtrl = list(maxfun = 50000)))
}

fit_item_mode <- function(df, facets) {
  # Expects columns: facets + item_id + score
  required <- c(facets, "item_id", "score")
  missing <- setdiff(required, names(df))
  if (length(missing) > 0) stop(paste("Missing columns:", paste(missing, collapse = ", ")))

  item_facets <- c(facets, "item_id")
  frm <- build_formula(item_facets, INTERACTION_TERMS, "score")
  cat("Fitting glmer:", deparse(frm), "\n")
  glmer(frm, data = df, family = binomial,
        control = glmerControl(optimizer = "bobyqa", optCtrl = list(maxfun = 100000)))
}

# ── Variance component extraction ───────────────────────────────────────────

extract_varcomps <- function(model) {
  vc <- as.data.frame(VarCorr(model))
  # vc columns: grp, var1, var2, vcov, sdcor
  out <- data.frame(
    facet    = vc$grp,
    variance = vc$vcov,
    stringsAsFactors = FALSE
  )
  resid_var <- attr(VarCorr(model), "sc")^2
  if (!is.na(resid_var) && resid_var > 0) {
    out <- rbind(out, data.frame(facet = "residual", variance = resid_var))
  }
  total <- sum(out$variance)
  out$pct_total <- round(out$variance / total * 100, 2)
  out
}

# ── Bootstrap CIs ───────────────────────────────────────────────────────────

bootstrap_varcomps <- function(model, n_boot) {
  cat(sprintf("Bootstrapping %d iterations...\n", n_boot))
  tryCatch({
    ci <- confint(model, method = "boot", nsim = n_boot, quiet = TRUE)
    # confint returns rows for fixed + random effects; extract random-effect rows
    re_names <- names(VarCorr(model))
    # Match row names like ".sig01", ".sig02", ... and ".sigma"
    sig_rows <- grep("^\\.sig", rownames(ci), value = TRUE)
    # Variances = sd^2, CIs on sd -> square them
    ci_var <- ci[sig_rows, , drop = FALSE]^2
    list(lower = ci_var[, 1], upper = ci_var[, 2])
  }, error = function(e) {
    cat("Bootstrap failed:", conditionMessage(e), "\n")
    cat("Falling back to profile CIs...\n")
    tryCatch({
      ci <- confint(model, method = "profile", quiet = TRUE)
      sig_rows <- grep("^\\.sig", rownames(ci), value = TRUE)
      ci_var <- ci[sig_rows, , drop = FALSE]^2
      list(lower = ci_var[, 1], upper = ci_var[, 2])
    }, error = function(e2) {
      cat("Profile CIs also failed:", conditionMessage(e2), "\n")
      NULL
    })
  })
}

# ── Output ───────────────────────────────────────────────────────────────────

write_results <- function(varcomps, ci_result, output_dir) {
  if (!dir.exists(output_dir)) dir.create(output_dir, recursive = TRUE)

  if (!is.null(ci_result)) {
    n_re <- nrow(varcomps)
    n_ci <- length(ci_result$lower)
    if (n_ci >= n_re) {
      varcomps$ci_lower <- ci_result$lower[1:n_re]
      varcomps$ci_upper <- ci_result$upper[1:n_re]
    } else {
      # CIs may exclude residual row
      varcomps$ci_lower <- c(ci_result$lower, rep(NA, n_re - n_ci))
      varcomps$ci_upper <- c(ci_result$upper, rep(NA, n_re - n_ci))
    }
  } else {
    varcomps$ci_lower <- NA_real_
    varcomps$ci_upper <- NA_real_
  }

  csv_path <- file.path(output_dir, "variance_components.csv")
  write_csv(varcomps, csv_path)
  cat("Wrote:", csv_path, "\n")

  json_path <- file.path(output_dir, "variance_components.json")
  json_out <- list(
    facets = varcomps$facet,
    variance = varcomps$variance,
    pct_total = varcomps$pct_total,
    ci_lower = varcomps$ci_lower,
    ci_upper = varcomps$ci_upper
  )
  write_json(json_out, json_path, pretty = TRUE, auto_unbox = TRUE)
  cat("Wrote:", json_path, "\n")

  cat("\n── Variance Components ──\n")
  print(varcomps, row.names = FALSE)
}

# ── Main ─────────────────────────────────────────────────────────────────────

main <- function() {
  opts <- parse_args()

  df <- read_csv(opts$input, show_col_types = FALSE)
  cat(sprintf("Read %d rows from %s\n", nrow(df), opts$input))

  # Normalize column names
  names(df) <- tolower(gsub("[^a-zA-Z0-9_]", "_", names(df)))
  if ("model_name" %in% names(df) && !"model" %in% names(df)) {
    df$model <- df$model_name
  }

  facets <- detect_available_facets(df, MAIN_FACETS)
  cat("Active facets:", paste(facets, collapse = ", "), "\n")
  if (length(facets) < 2) stop("Need at least 2 facets with ≥2 levels each")

  df <- ensure_factors(df, c(facets, "item_id"))

  model <- if (opts$mode == "item") {
    fit_item_mode(df, facets)
  } else {
    fit_condition_mode(df, facets)
  }

  cat("\nModel summary:\n")
  print(summary(model))

  varcomps <- extract_varcomps(model)
  ci_result <- bootstrap_varcomps(model, opts$n_boot)
  write_results(varcomps, ci_result, opts$output_dir)
}

main()

